const authoredMedia = attachPhotoMetadata(MEDIA_ROWS.map(([
  id,
  category,
  sourceOrder,
  productKey,
  titleVi,
  titleEn,
  sourceId,
  src,
  width,
  height,
]) => Object.freeze({
  id,
  category,
  sourceOrder,
  productKey,
  titleVi,
  titleEn,
  media: Object.freeze({
    sourceId,
    src,
    width,
    height,
  }),
})));

